   168  static int can_run_requests(h2o_http2_conn_t *conn)
   169  {
   170      return conn->num_streams.pull.half_closed + conn->num_streams.push.half_closed <
   171             conn->super.ctx->globalconf->http2.max_concurrent_requests_per_connection;
