   174  static void run_pending_requests(h2o_http2_conn_t *conn)
   175  {
   176      h2o_linklist_t *link, *lnext;
   177      int ran_one_request;
   178
   179      do {
   180          ran_one_request = 0;
   181
   182          for (link = conn->_pending_reqs.next; link != &conn->_pending_reqs && can_run_requests(conn); link = lnext) {
   183              /* fetch and detach a pending stream */
   184              h2o_http2_stream_t *stream = H2O_STRUCT_FROM_MEMBER(h2o_http2_stream_t, _refs.link, link);
   185
   186              lnext = link->next;
   187
   188              if (stream->req._write_req_chunk_done != NULL) {
   189                  if (conn->num_streams._request_body_in_progress) {
   190                      continue;
   191                  }
   192                  conn->num_streams._request_body_in_progress++;
   193                  stream->_conn_stream_in_progress = 1;
   194              } else {
   195                  if (stream->state < H2O_HTTP2_STREAM_STATE_SEND_HEADERS) {
   196                      h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_REQ_PENDING);
   197                      h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_SEND_HEADERS);
   198                  }
   199              }
   200
   201              h2o_linklist_unlink(&stream->_refs.link);
   202              ran_one_request = 1;
   203
   204              /* handle it */
   205              if (!h2o_http2_stream_is_push(stream->stream_id) && conn->pull_stream_ids.max_processed < stream->stream_id)
   206                  conn->pull_stream_ids.max_processed = stream->stream_id;
   207              h2o_process_request(&stream->req);
   208          }
   209
   210      } while (ran_one_request && !h2o_linklist_is_empty(&conn->_pending_reqs));
   211  }
